# region: sift
def sift(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: digest
def digest(xs, offset=-1):
    return [v - offset for v in xs]

# region: gather
def gather(xs):
    return [v * v for v in xs]

# region: emit
def emit(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: intake
def intake(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return intake(emit(gather(digest(sift(raw)))))

